{
  "title": "Ngày Đà Lạt trong nhà, mưa không lo",
  "summary": "Trời mưa thì mình đổi hết sang chỗ có mái che, vẫn đủ vị Đà Lạt từ bảo tàng đến cà phê tối, nhẹ nhàng và ấm cúng.",
  "stops": [
    {
      "poi_id": "p23",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mưa ngoài kia thì vào Lam Dong Museum ngắm lịch sử và văn hoá, khô ráo lại vừa đúng kiểu đi chậm."
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh căn nóng hổi trong quán có mái, ăn xong nghe mưa rơi ngoài hiên cũng vui."
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "Domaine De Marie mái ngói đỏ che mưa tốt, vừa ngắm kiến trúc vừa thấy lòng nhẹ tênh."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nem nướng Bà Hùng ngồi bàn trong nhà, cuốn rau thơm đầy đặn, ngon quá (so tasty) là đúng bài."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối mưa thì Mây Lang Thang là chỗ trốn lý tưởng, cà phê ấm và ánh đèn vàng làm tôi quên luôn ngoài trời đang ướt."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Marché khu vui chơi trong nhà cho cú đêm, đi bộ loanh quanh nghe nhạc mà không ướt một giọt."
    }
  ]
}
```

